parameters.jsCode:
const f = $('Receive AI System Details').first().json;
const p = $('Set Classification Policy').first().json;
const cats = $input.all().map(i => i.json).filter(r => r && r.annex_point);
const clip = (s, n) => String(s == null ? '' : s).slice(0, n);
const low = v => clip(v, 4000).trim().toLowerCase();
const isYes = v => low(v) === 'yes';
const purpose = low(f.purpose_and_context);
const effect = low(f.decision_effect);
const hay = purpose + ' ' + low(f.system_name) + ' ' + effect;
const affectsPeople = isYes(f.affects_natural_persons);
const signals = [];
let score = 0;
const add = (w, code, detail) => { score = score + w; signals.push({ weight: w, code: code, detail: detail }); };
// Keyword matching must not fire on a fragment inside a longer word. Plain
// indexOf once matched 'election' inside 'employment selection' and tagged a CV
// screener as a democratic-processes system. Require a word boundary BEFORE the
// keyword, but leave the end open so 'reject' still matches 'rejected'.
const esc = t => t.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
const has = (text, w) => new RegExp('(^|[^a-z0-9])' + esc(w)).test(text);
const PROHIBITED = [
  { code: 'ART5_SOCIAL_SCORING', any: ['social scoring', 'social score', 'trustworthiness score', 'citizen score'], detail: 'Article 5(1)(c): scoring people on general social behaviour or personal traits, leading to detrimental treatment in unrelated contexts' },
  { code: 'ART5_EMOTION_AT_WORK', any: ['emotion recognition', 'emotion detection', 'mood detection', 'infer emotion'], also: ['workplace', 'employee', 'staff', 'education', 'student', 'classroom', 'candidate', 'interview'], detail: 'Article 5(1)(f): inferring emotions of a person in the workplace or in education. Two limits to check before you act on this. The prohibition covers emotions inferred from biometric data, and it exempts systems intended for medical or safety reasons. If either applies to you, this is not automatically prohibited and needs a documented assessment.' },
  { code: 'ART5_UNTARGETED_SCRAPING', any: ['untargeted scraping', 'scrape facial', 'scraping facial', 'facial images from the internet'], detail: 'Article 5(1)(e): untargeted scraping of facial images from the internet or CCTV to build or expand a facial recognition database' },
  { code: 'ART5_PREDICTIVE_POLICING', any: ['predictive policing', 'predict crime', 'likelihood of committing', 'risk of committing a crime'], detail: 'Article 5(1)(d): predicting the risk of a person committing a criminal offence based solely on profiling or personality traits. Does not cover systems that support a human assessment already grounded in objective, verifiable facts.' },
  { code: 'ART5_MANIPULATION', any: ['subliminal', 'manipulate behaviour', 'manipulate behavior', 'exploit vulnerabilit'], detail: 'Article 5(1)(a) and (b): subliminal or purposefully manipulative techniques, or exploiting the vulnerabilities of a person or group, where this distorts behaviour and causes significant harm' }
];
const prohibited = [];
for (const r of PROHIBITED) {
  const hit = r.any.some(w => has(hay, w));
  const ctx = r.also ? r.also.some(w => has(hay, w)) : true;
  if (hit && ctx) { prohibited.push(r.code); add(0, r.code, r.detail); }
}
const registerEmpty = cats.length === 0;
const matched = [];
for (const c of cats) {
  const words = low(c.keywords).split(',').map(s => s.trim()).filter(Boolean);
  const hits = words.filter(w => w.length > 2 && has(hay, w));
  if (hits.length) { matched.push({ annex_point: String(c.annex_point), area_name: c.area_name, matched_on: hits.slice(0, 5), obligation_note: c.obligation_note || '' }); }
}
if (registerEmpty) {
  add(0, 'CATEGORY_REGISTER_EMPTY', 'The Annex III category table returned no rows, so nothing could be matched against it. This run checked Article 5 patterns and the questionnaire only. Seed the table before treating any verdict from this workflow as meaningful.');
} else if (matched.length) {
  const areas = matched.map(m => 'point ' + m.annex_point + ' (' + m.area_name + ')').join('; ');
  add(45, 'ANNEX_III_AREA_MATCH', 'The described purpose matches Annex III ' + areas + '. Matched on: ' + matched.map(m => m.matched_on.join('/')).join(' | '));
} else {
  add(0, 'NO_ANNEX_III_MATCH', 'No Annex III area matched the described purpose on keywords, across ' + cats.length + ' registered area(s). That is not a clearance - the wording may simply not use the terms in your register.');
}
if (affectsPeople) { add(15, 'AFFECTS_NATURAL_PERSONS', 'The system produces outcomes about identifiable people, which is what brings Annex III into play at all'); }
const legalWords = ['legal effect', 'reject', 'refuse', 'deny', 'eligibility', 'shortlist', 'terminate', 'suspend', 'grant', 'creditworth', 'admission'];
const effectHits = legalWords.filter(w => has(effect, w));
if (effectHits.length && affectsPeople) { add(20, 'SIGNIFICANT_EFFECT', 'The stated effect changes what a person gets or is refused, which is the threshold Article 86 and Annex III both care about. Matched on: ' + effectHits.join(', ')); }
else if (effectHits.length && !affectsPeople) { add(0, 'EFFECT_WORDING_BUT_NO_PERSON', 'The effect wording matched ' + effectHits.join(', ') + ' but you answered that no natural person is affected, so it was not scored. If people are in fact affected, answer Yes and run this again.'); }
if (isYes(f.uses_biometric_or_emotion_data)) { add(15, 'BIOMETRIC_OR_EMOTION_DATA', 'Biometric or emotion data is in scope of Annex III point 1, and some uses are prohibited outright under Article 5'); }
if (low(f.human_reviews_every_decision) === 'no' && affectsPeople) { add(10, 'NO_HUMAN_REVIEW', 'No human reviews each decision, so Article 14 human oversight cannot be satisfied by the review step alone'); }
const DEROGATION = ['narrow procedural', 'preparatory', 'improves the result of a previous human', 'human makes the final', 'human decides', 'detects decision patterns'];
const derog = DEROGATION.filter(w => has(purpose, w));
if (derog.length && !isYes(f.uses_biometric_or_emotion_data)) { add(-25, 'ART6_3_DEROGATION_CANDIDATE', 'The description suggests an Article 6(3) derogation such as a narrow procedural or preparatory task. All four conditions must be met and read narrowly, it must be documented and registered before you rely on it, and it never applies if the system profiles natural persons.'); }
const TRANSPARENCY = ['chatbot', 'chat assistant', 'generates text', 'generates image', 'synthetic', 'deepfake', 'voice clone', 'content generation'];
const transparency = TRANSPARENCY.some(w => has(hay, w));
if (transparency) { add(0, 'ART50_TRANSPARENCY', 'The system interacts with people or generates synthetic content, so Article 50 disclosure duties apply regardless of the risk tier'); }
if (low(f.placed_on_eu_market) === 'no') { add(0, 'EU_SCOPE_UNCLEAR', 'Marked as not placed on the EU market. The Act still reaches systems whose output is used in the EU, so confirm scope before treating this as out of scope.'); }
return [{ json: {
  system_name: clip(f.system_name, 200),
  owner_team: clip(f.owner_team, 200),
  our_role: clip(f.our_role, 40),
  purpose: clip(f.purpose_and_context, 6000),
  prohibited_codes: prohibited,
  annex_matches: matched,
  annex_points: matched.map(m => m.annex_point).join(', '),
  transparency_duty: transparency,
  register_empty: registerEmpty,
  deterministic_score: Math.max(0, Math.min(score, 100)),
  signals: signals,
  category_count: cats.length,
  high_risk_at: p.high_risk_at,
  review_at: p.review_at,
  ai_max_points: p.ai_max_points
} }];

