Described purpose and context:
{{ $('Match Deterministic Rule Signals').item.json.purpose }}

parameters.jsCode:
const s = $('Match Deterministic Rule Signals').first().json;
const raw = $input.first().json || {};
const ai = raw.output ? raw.output : raw;
const signals = s.signals.slice();
let score = s.deterministic_score;
const cap = Number(s.ai_max_points) || 20;
const rawConf = Number(ai.confidence) || 0;
const conf = (rawConf > 0 && rawConf <= 1) ? Math.round(rawConf * 100) : Math.max(0, Math.min(Math.round(rawConf), 100));
const aiPoints = Array.isArray(ai.likely_annex_points) ? ai.likely_annex_points.map(x => String(x)).slice(0, 8) : [];
const modelAnswered = aiPoints.length > 0 || rawConf > 0 || typeof ai.rationale === 'string';
if (!modelAnswered) { signals.push({ weight: 0, code: 'MODEL_DID_NOT_ANSWER', detail: 'The language model returned nothing usable, so this verdict rests on the deterministic rules alone. That is by design rather than a failure, but it means the free-text purpose was not read.' }); }
const known = s.annex_points ? s.annex_points.split(', ').filter(Boolean) : [];
const extra = aiPoints.filter(x => known.indexOf(x) === -1);
if (aiPoints.length) {
  const w = Math.round((conf / 100) * cap);
  score = score + w;
  signals.push({ weight: w, code: 'MODEL_ANNEX_ASSESSMENT', detail: 'The model placed this in Annex III point(s) ' + aiPoints.join(', ') + ' at ' + conf + ' of 100 confidence, worth ' + w + ' of a possible ' + cap + ' points. ' + String(ai.rationale || '').slice(0, 300) });
}
if (extra.length) { signals.push({ weight: 0, code: 'MODEL_FOUND_EXTRA_AREA', detail: 'The model suggested Annex III point(s) ' + extra.join(', ') + ' that keyword matching missed. Read the description yourself before dismissing them.' }); }
if (ai.profiles_natural_persons === true) { signals.push({ weight: 0, code: 'PROFILES_NATURAL_PERSONS', detail: 'The model judged that this profiles natural persons, which removes the Article 6(3) derogation even for a narrow procedural task' }); }
score = Math.max(0, Math.min(score, 100));
const isProhibited = Array.isArray(s.prohibited_codes) && s.prohibited_codes.length > 0;
const hasArea = (s.annex_points && s.annex_points.length > 0) || aiPoints.length > 0;
const registerEmpty = s.register_empty === true;
let tier = 'MINIMAL_RISK';
if (isProhibited) { tier = 'PROHIBITED'; }
else if (hasArea && score >= s.high_risk_at) { tier = 'HIGH_RISK'; }
else if (hasArea && score >= s.review_at) { tier = 'NEEDS_REVIEW'; }
else if (registerEmpty) { tier = 'NEEDS_REVIEW'; }
else if (s.transparency_duty) { tier = 'LIMITED_RISK'; }
const HIGH_OBLIGATIONS = [
  'Article 9 risk management system, maintained across the lifecycle',
  'Article 10 data governance for training, validation and testing data',
  'Article 11 and Annex IV technical documentation',
  'Article 12 automatic logging, retained for the required period',
  'Article 13 instructions for use that let a deployer interpret the output',
  'Article 14 human oversight designed into the system, not bolted on',
  'Article 15 accuracy, robustness and cybersecurity, with declared metrics',
  'Article 49 registration in the EU database before use',
  'Article 26 deployer duties: use per instructions, assign competent oversight, keep logs, inform affected workers',
  'Article 27 fundamental rights impact assessment, for public bodies and certain private deployers',
  'Article 86 right to an explanation of the individual decision, applicable since 2 August 2026'
];
const LIMITED_OBLIGATIONS = [
  'Article 50(1) tell people they are interacting with an AI system',
  'Article 50(2) mark synthetic content as machine readable',
  'Article 50(4) disclose deepfakes and AI-generated text published on matters of public interest'
];
let obligations = [];
if (tier === 'PROHIBITED') { obligations = ['Article 5 prohibits this practice. Prohibitions have applied since 2 February 2025. Check the narrow exception named in the finding below before you act, then take legal advice. Do not attempt to mitigate a prohibited practice into compliance.']; }
else if (tier === 'HIGH_RISK') { obligations = HIGH_OBLIGATIONS; }
else if (tier === 'NEEDS_REVIEW' && registerEmpty) { obligations = ['Seed the Annex III category table, then run this again. Until then this workflow cannot tell you whether the system is in an Annex III area, and nothing here should be read as a clearance.']; }
else if (tier === 'NEEDS_REVIEW') { obligations = ['Treat as high-risk until a documented assessment says otherwise, and keep that assessment.'].concat(HIGH_OBLIGATIONS.slice(0, 4)); }
if (s.transparency_duty) { obligations = obligations.concat(LIMITED_OBLIGATIONS); }
if (!obligations.length) { obligations = ['No high-risk or transparency duty identified from this description. Keep the record and re-screen when the purpose changes.']; }
const notes = (s.annex_matches || []).map(m => 'Point ' + m.annex_point + ': ' + m.obligation_note).filter(x => x.length > 10);
const ordered = signals.slice().sort((a, b) => b.weight - a.weight);
const lines = ordered.map(x => '[' + x.weight + '] ' + x.code + ': ' + x.detail);
const action = tier === 'PROHIBITED' ? 'Stop. This looks like an Article 5 prohibited practice. Check the exception named below, then take legal advice.' : (tier === 'HIGH_RISK' ? 'Treat as high-risk. Assign an owner to the obligations below and register the system before it is used.' : (tier === 'NEEDS_REVIEW' ? (registerEmpty ? 'Cannot answer. The category register is empty, so this run had nothing to match against.' : 'Borderline. A human needs to make and document this call rather than accept a score.') : (tier === 'LIMITED_RISK' ? 'Not high-risk on this description, but the Article 50 disclosure duties still apply.' : 'No duties identified from this description. Re-screen when the purpose changes.')));
return [{ json: {
  risk_tier: tier,
  risk_score: score,
  system_name: s.system_name,
  owner_team: s.owner_team,
  our_role: s.our_role,
  annex_points: s.annex_points || aiPoints.join(', '),
  model_points: aiPoints.join(', '),
  model_confidence: conf,
  model_answered: modelAnswered,
  register_empty: registerEmpty,
  transparency_duty: s.transparency_duty,
  obligations: obligations,
  obligations_text: obligations.map((o, i) => (i + 1) + '. ' + o).join('\n'),
  category_notes: notes.join('\n'),
  signal_codes: ordered.map(x => x.code).join(', '),
  recommended_action: action,
  assessed_at: new Date().toISOString(),
  report: lines.join('\n')
} }];

